ee:variables.ee:set-variable:
%dw 2.0
output application/java
import resolveProp from dwl::assessment
---
(vars.warnings default []) ++ (do {
    var ds       = vars.deployedState default {}
    var deployed = (ds.runtimeVersion default null)
    var source   = (resolveProp(vars.chain, "app.runtime") default resolveProp(vars.chain, "app.runtime.semver") default null)
    ---
    if ((ds.found default false) and deployed != null and source != null and (lower(trim(deployed as String)) != lower(trim(source as String))))
        [ ("NOTE: " ++ (vars.appName default 'this app') ++ " is deployed on Mule runtime " ++ (deployed as String)
           ++ " in '" ++ (vars.environment default '?') ++ "', but the source pom declares " ++ (source as String)
           ++ ". The change plan is computed from source (Git); confirm the deployed app matches the branch being upgraded.") ]
    else if (ds.found default false)
        []
    else if (!(ds.reachable default false))
        [ ("NOTE: Runtime Manager could not be reached during assessment for '" ++ (vars.appName default 'this app')
           ++ "' in '" ++ (vars.environment default '?') ++ "'; the assessment is based on source (Git) only.") ]
    else
        [ ("NOTE: no running deployment was found in Runtime Manager for '" ++ (vars.appName default 'this app')
           ++ "' in environment '" ++ (vars.environment default '?') ++ "'; the assessment is based on source (Git) only.") ]
})
